"""Generate the reviewable concept atlas and per-game dossier from authored data."""
from pathlib import Path
import json

ROOT = Path(__file__).parent
data = json.loads((ROOT / 'ui-ux-game-concepts-2026.json').read_text())
games = data['games']
fields = [('finding','Auditbefund'),('fantasy','Core Fantasy'),('rule','10-Sekunden-Regel'),('device','Beste Spielweise und Übergabe'),('layout','UI und Art Direction'),('loop','Einstieg und Game Loop'),('reveal','Reveal'),('finale','Finale'),('replay','Wiederspielwert'),('edge','Sonderfälle und Grenzen'),('acceptance','Abnahme')]
md = (ROOT / 'ui-ux-audit-premium-2026.md').read_text().split('<!-- GAME_PROFILES -->')[0]
md += '<!-- GAME_PROFILES -->\n\n'
md += '| # | Spiel | Empfohlene Spielweise | Format |\n| --- | --- | --- | --- |\n'
for i,g in enumerate(games,1):
    md += f"| {i:02} | {g['title']} | {g['mode']} | {g['duration']} |\n"
for i,g in enumerate(games,1):
    md += f"\n### {i:02} · {g['title']}\n\n**{g['world']} · {g['mode']}**\n\n{g['duration']}\n\n"
    for key,label in fields:
        md += f"**{label}.** {g[key]}\n\n"
    md += f"**Beispiel-Copy:** „{g['prompt']}“ → **{g['cta']}** → „{g['moment']}“\n"
(ROOT / 'ui-ux-audit-premium-2026.md').write_text(md)

doc = r'''<!doctype html>
<html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>NOCTURNE · 27 Erlebnisentwürfe</title>
<style>
:root{color-scheme:dark;--bg:#111315;--panel:#1a1d20;--ink:#f3f0e8;--muted:#b2b7bb;--line:#383d42;--accent:#f2a7ae}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 system-ui,sans-serif}button,input,select{font:inherit}button{cursor:pointer}a{color:inherit}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid var(--accent);outline-offset:4px}header{padding:30px 4vw;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:22px}header strong{font:26px Georgia,serif;letter-spacing:.2em}.meta,.eyebrow{font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}header p{margin:0;color:var(--muted);font-size:13px}.wrap{display:grid;grid-template-columns:270px minmax(0,1fr);max-width:1600px;margin:auto}aside{border-right:1px solid var(--line);padding:26px 20px;position:sticky;top:0;height:100vh;overflow:auto}input{width:100%;padding:12px;background:#22272b;color:var(--ink);border:1px solid #555d63;border-radius:9px;margin:14px 0}nav{display:grid;gap:4px}nav button{text-align:left;border:0;border-radius:8px;padding:12px;color:#c1c6cb;background:none;min-height:48px;font-size:14px}nav button[aria-current=true]{background:#2b3035;color:#fff;box-shadow:inset 3px 0 var(--accent)}.num{font:11px ui-monospace,monospace;color:#9ba2a9;display:inline-block;min-width:25px}.group{margin:20px 8px 8px;font-size:10px;text-transform:uppercase;letter-spacing:.18em;color:#b9bfc6}main{padding:38px clamp(20px,4vw,64px) 80px;min-width:0}.topline{display:flex;justify-content:space-between;gap:15px;align-items:center}.pill{display:inline-flex;padding:6px 11px;border:1px solid #5c6267;border-radius:30px;font-size:11px;letter-spacing:.04em}.title{font:clamp(38px,4.4vw,66px)/1.07 Georgia,serif;letter-spacing:-.04em;margin:22px 0 14px}.lede{max-width:780px;font-size:20px;color:#d2d6d8;margin:0 0 24px}.tabs{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:18px}.tabs button{background:none;border:1px solid #444b52;color:#c2c9cf;border-radius:30px;min-height:44px;padding:9px 16px;font-size:13px}.tabs button[aria-pressed=true]{background:var(--ink);color:#151719;border-color:var(--ink)}.stage{border:1px solid #4c535a;border-radius:18px;overflow:hidden;position:relative;background:#090c10;min-height:420px;display:flex;flex-direction:column;padding:26px 32px;box-shadow:0 24px 70px #0002}.stage-top{display:flex;justify-content:space-between;align-items:center;gap:14px;font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:#b1b9c0}.stage-body{min-height:280px;display:flex;flex-direction:column;justify-content:center;padding:30px 0;gap:24px}.stage h2{font:clamp(27px,3.1vw,48px)/1.18 Georgia,serif;letter-spacing:-.025em;max-width:22ch;margin:0}.stage-bottom{display:flex;align-items:center;justify-content:space-between;gap:18px}.action{border:0;background:var(--accent);color:#11151b;min-height:48px;border-radius:9px;padding:12px 22px;font-weight:650}.quiet{background:none;border:0;color:#b8c0c5;min-height:44px;padding:10px}.stage-note{font-size:11px;color:#a5aeb6;margin:12px 2px 26px}.split{display:grid;grid-template-columns:1fr 1fr;gap:16px}.tile{padding:22px;border:1px solid #68717a;border-radius:10px;background:#ffffff07;min-width:0}.tile h3{font:24px/1.25 Georgia,serif;margin:8px 0}.tile small{color:#c8d0d6}.accent{color:var(--accent)}.big{font:clamp(68px,10vw,120px)/1 Georgia,serif;letter-spacing:-.06em}.center{text-align:center;align-items:center}.center h2{margin:auto}.timer-ring{width:180px;height:180px;border:3px solid var(--accent);border-radius:50%;display:grid;place-items:center;margin:auto}.timer-ring span{font:80px/1 Georgia,serif}.track{min-height:150px;aspect-ratio:1.4;display:flex;flex-direction:column;justify-content:flex-end;background:linear-gradient(145deg,#283643,#111820);padding:20px;border-radius:12px;border:1px solid #69737c}.track:last-child{background:linear-gradient(145deg,#513c4b,#1e1d27)}.track b{font:30px Georgia,serif}.rail{display:flex;gap:10px;align-items:stretch}.rail>span{flex:1;padding:18px 8px;border-top:3px solid var(--accent);font-size:14px;text-align:center}.score{display:flex;justify-content:space-between;align-items:center;gap:15px}.score strong{font:70px Georgia,serif}.bars{display:grid;gap:12px}.bar{display:grid;grid-template-columns:90px 1fr 30px;gap:12px;align-items:center;font-size:14px}.bar i{height:26px;width:var(--w);background:var(--accent);border-radius:3px}.secret{max-width:330px;align-self:center;width:100%;padding:30px;border:1px solid var(--accent);border-radius:16px;text-align:center;background:linear-gradient(150deg,#292838,#10151b)}.secret .seal{font:65px Georgia,serif;margin:8px 0}.line{height:3px;background:var(--accent);margin:35px 0;position:relative}.line:before,.line:after{content:'';position:absolute;top:-7px;width:17px;height:17px;border:2px solid var(--accent);border-radius:50%;background:#10151b}.line:after{right:0}.poles{display:flex;justify-content:space-between;gap:30px;font-size:20px}.note{border-left:3px solid var(--accent);padding:5px 0 5px 22px;font:27px/1.35 Georgia,serif}.gallery{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.photo{height:150px;border:1px dashed #77838b;display:grid;place-items:center;border-radius:10px;color:#bdc7ce;font-size:12px;background:#202830}.diagram{display:block;width:100%;max-height:180px;stroke:var(--accent);stroke-width:3;fill:none}.panic{align-self:center;border:10px solid #3c2822;background:var(--accent);color:#1b1716;width:180px;height:180px;border-radius:50%;font:70px Georgia,serif;display:grid;place-items:center}.factgrid{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:30px}.factgrid section{border-top:1px solid var(--line);padding-top:18px}.factgrid h3{font-size:11px;letter-spacing:.13em;text-transform:uppercase;color:var(--accent);margin:0 0 10px}.factgrid p{color:#c1c8ce;font-size:15px;margin:0}.audit{margin-top:28px;background:#20262b;border:1px solid #46505a;padding:20px 24px;border-radius:10px}.audit h3{font-size:12px;text-transform:uppercase;letter-spacing:.12em;margin:0 0 10px}.audit p{margin:0;font-size:14px;color:#c2cad1}.intro-title{font-size:46px!important}.light{background:#efe9df;color:#232626}.light .stage-top,.light .quiet,.light small{color:#545a5b}.light .action{background:#293336;color:#fff}.light h2{max-width:24ch}.empty{color:#b6c0c8;padding:14px}.footer-note{font-size:12px;color:#b2bac2;margin-top:36px}.summary{margin:0 0 28px;border-left:2px solid #a4b4a1;padding-left:18px;font-size:14px;color:#bcc5cc}details{margin-top:25px;border-top:1px solid var(--line);padding-top:18px}summary{cursor:pointer;padding:8px 0;font-size:14px;color:#d6dce1}details p{font-size:14px;color:#bac4cc}.handoff-name{font:56px Georgia,serif}.screen-pair{display:grid;grid-template-columns:1.5fr 1fr;gap:22px}.screen-pair .tile{display:flex;flex-direction:column;justify-content:center}.stage-tag{display:inline-block;font:11px system-ui,sans-serif;letter-spacing:.12em;color:var(--accent);margin-bottom:18px}.completion{border-top:1px solid #68717a;padding-top:15px;font-size:14px;color:#cbd1d7}@media(max-width:900px){.wrap{grid-template-columns:210px minmax(0,1fr)}main{padding:28px 20px}.stage{padding:22px}.factgrid{grid-template-columns:1fr}.screen-pair{grid-template-columns:1fr}}@media(max-width:650px){header{padding:22px;align-items:flex-start;flex-direction:column;gap:8px}.wrap{display:block}aside{height:auto;position:static;border-right:0;border-bottom:1px solid var(--line);padding:16px 20px}nav{max-height:180px;overflow:auto;grid-template-columns:1fr 1fr}.group{grid-column:1/-1;margin:8px}.topline{align-items:flex-start;flex-direction:column}.title{font-size:40px}.lede{font-size:18px}.stage{border-radius:12px;padding:18px;min-height:430px}.stage-body{min-height:290px}.stage h2{font-size:30px}.split{gap:10px}.tile{padding:13px}.track{padding:14px;min-height:135px}.track b{font-size:23px}.bar{grid-template-columns:65px 1fr 20px}.stage-bottom{align-items:stretch;flex-direction:column;gap:3px}.gallery{gap:6px}.photo{height:110px}.stage-top{font-size:9px}.poles{font-size:17px}.score strong{font-size:53px}.pill{font-size:10px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}@media print{header,aside,.tabs,.stage-bottom{display:none}.wrap{display:block}main{padding:0}.stage{box-shadow:none}.factgrid{display:block}.factgrid section{break-inside:avoid}}
.light .stage-tag{color:#4b5b56}.light .completion{color:#46524f;border-color:#a0aaa3}.light .secret{color:#f3f0e8}.light .secret small{color:#c8d0d6}
</style></head><body>
<header><strong>NOCTURNE</strong><div><p>27 Spiele. 27 eigene Erlebnisse.</p><span class="meta">UI/UX-Konzeptatlas · 25.10.2026 · Entwurf</span></div></header>
<div class="wrap"><aside><label for="search" class="eyebrow">Spiel finden</label><input id="search" type="search" placeholder="Name oder Spielweise …"><nav id="games" aria-label="Alle Spielkonzepte"></nav></aside>
<main id="concept"><div class="summary">Premium bedeutet: Die Bedienung trägt den Spielmoment. Ein Handy, eine gute Übergabe oder ein ganzer Raum – je nachdem, was das Game besser macht.</div><div class="topline"><span id="world" class="eyebrow"></span><span id="mode" class="pill"></span></div><h1 id="title" class="title"></h1><p id="fantasy" class="lede"></p>
<div class="tabs" role="group" aria-label="Konzeptansicht"><button data-view="intro" aria-pressed="false">Einstieg</button><button data-view="moment" aria-pressed="true">Spielmoment</button><button data-view="finale" aria-pressed="false">Reveal & Finale</button><button data-view="handoff" aria-pressed="false">Übergabe-Prinzip</button></div>
<div class="stage" id="stage" aria-label="Illustrativer Spielscreen"></div><p class="stage-note">Gestaltungsbeispiel mit fiktiven Namen und Ergebnissen. Keine laufende Session, kein echter Ton. Die Ansichtsbuttons wechseln die Entwurfszustände.</p>
<div class="factgrid" id="details"></div><div class="audit"><h3>Audit · beobachteter Ausgangsstand</h3><p id="finding"></p></div><details><summary>Prüfumfang und Status</summary><p>Alle 25 sichtbaren Spielvorstellungen wurden öffentlich geprüft, die laufenden Abläufe quellenbasiert auditiert. FIRST//BEAT und TIME//DROP sind vorhandene Spielkerne. Keine vollständige bezahlte Session, reale Mobilgeräte- oder 99-Personen-Abnahme in diesem Audit. Dieses Board ist ein visueller Entwurf; technische Umsetzung und menschliche Spieltests stehen separat.</p></details><p class="footer-note">SMART MISCHIEF · Klarheit vor Humor. Die Situation necken, niemanden bloßstellen.<br>Detailregeln, Sonderfälle und Abnahme stehen im begleitenden Audit-Dossier.</p></main></div>
<noscript>Dieses Konzeptboard benötigt JavaScript. Das vollständige Audit ist als Markdown-Dossier beigefügt.</noscript>
<script>
const GAMES=__DATA__;
const $=id=>document.getElementById(id);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let current=GAMES[0],view='moment',handoff=0;
function nav(){let q=$('search').value.toLocaleLowerCase('de');let last='';$('games').innerHTML=GAMES.map((g,i)=>({g,i})).filter(({g})=>(g.title+' '+g.mode+' '+g.world).toLocaleLowerCase('de').includes(q)).map(({g,i})=>{let group=g.world===last?'':`<div class="group">${esc(g.world)}</div>`;last=g.world;return group+`<button data-game="${esc(g.id)}" aria-current="${current.id===g.id}"><span class="num">${String(i+1).padStart(2,'0')}</span>${esc(g.title)}</button>`}).join('')||'<p class="empty">Kein passendes Spiel.</p>';document.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>{current=GAMES.find(g=>g.id===b.dataset.game);handoff=0;render();});}
const tile=(a,b)=>`<div class="tile"><small>${a}</small><h3>${b}</h3></div>`;
function art(g){const p=`<h2>${esc(g.prompt)}</h2>`;switch(g.visual){
case 'spark':return p+`<div class="split">${tile('ARI · DEIN ZUG','Ein gemeinsames Talent?')}${tile('NOVA · ALS NÄCHSTES','Ich bin gespannt.')}</div>`;
case 'timer':return `<div class="screen-pair">${p}<div class="timer-ring"><span>20</span></div></div><span class="eyebrow">Timer startet erst, wenn ihr bereit seid</span>`;
case 'route':return p+'<div class="rail"><span>Lustiger</span><span>Näher</span><span>Spielerischer</span></div><div class="note">Die nächsten drei Szenen folgen eurer Wahl.</div>';
case 'duel':return '<div class="score"><span>Ari<br><strong>6</strong></span><span class="accent">VS</span><span>Nova<br><strong>4</strong></span></div>'+p+'<div class="completion">Optionaler Einsatz: ×2 · vor dem Duell wählen</div>';
case 'vault':return p+'<div class="split">'+tile('EUER VAULT','Noch ein gemeinsamer Moment.')+tile('BEISPIEL-FORTSCHRITT','Lachen ✓<br>Nähe ✓<br>Spannung ·')+'</div>';
case 'minimal':return '<span class="eyebrow">NOVA · DEINE FRAGE</span>'+p+'<p>Kein Timer. Kein Punktestand. Ihr habt Zeit.</p>';
case 'echo':return '<span class="eyebrow">ECHO AUS EURER NACHT · BEISPIEL</span><div class="note">„Erst Pommes, dann Pläne.“</div>'+p;
case 'director':return '<div class="rail"><span>Szene</span><span>Wechsel</span><span>Callback</span></div>'+p+'<div class="note">Regie, die Platz für euch lässt.</div>';
case 'tracks':return p+'<div class="split"><div class="track"><small>DEMO · TRACK A</small><b>Dein Song</b><span>Titel & Interpret</span></div><div class="track"><small>DEMO · TRACK B</small><b>Mein Song</b><span>Titel & Interpret</span></div></div>';
case 'majority':return p+'<div class="bars">'+[['Essen',50,4],['Musik',37.5,3],['Ortswechsel',12.5,1]].map(([n,w,v])=>`<div class="bar"><span>${n}</span><i style="--w:${w*1.7}%"></i><b>${v}</b></div>`).join('')+'</div><small>Illustratives Ergebnis · acht Stimmen</small>';
case 'spotlight':return '<span class="eyebrow">DER RAUM IST DRAN</span>'+p+'<div class="split">'+tile('IM SPOTLIGHT','Ari')+tile('ERST GEMEINSAM','3 · 2 · 1')+'</div>';
case 'sealed':return p+'<div class="secret"><small>NUR FÜR DICH</small><div class="seal">?</div><span>Privat ansehen. Dann wieder verdecken.</span></div>';
case 'missions':return '<span class="eyebrow">DEIN GEHEIMER AUFTRAG</span>'+p+'<div class="completion">Läuft neben eurem Abend. Niemand muss warten.</div>';
case 'comedy':return p+'<div class="note">„Damit das WLAN Urlaub nehmen kann.“</div><small>Fiktiver Gag · Urheber erst nach der Wahl</small>';
case 'bluff':return p+'<div class="split">'+tile('ANTWORT A','Plausibel. Oder?')+tile('ANTWORT B','Klingt auch richtig.')+'</div><span class="eyebrow">Identische Darstellung · keine verräterische Formatierung</span>';
case 'line':return p+'<div><div class="poles"><span>Einfach los</span><span>Alles geplant</span></div><div class="line"></div></div><small>Ihr seid die Marker. Der Raum ist die Skala.</small>';
case 'teams':return '<div class="split">'+tile('TEAM SONNE','6 Punkte')+tile('TEAM MOND','6 Punkte')+'</div>'+p;
case 'gallery':return p+'<div class="gallery"><div class="photo">Foto A · Platzhalter</div><div class="photo">Foto B · Platzhalter</div><div class="photo">Foto C · Platzhalter</div></div>';
case 'drawing':return p+'<svg class="diagram" viewBox="0 0 400 160" aria-label="Illustrative Zeichnung eines Stuhls" role="img"><path d="M120 100L250 96L286 116L153 121Z M120 100L117 35L244 31L250 96 M153 121L150 155 M286 116L289 153 M124 103L120 145 M251 98L257 143"/></svg><small>Papier-Couch: echte Zeichnung im Raum, Timer auf dem Screen.</small>';
case 'chain':return p+'<div class="rail"><span>Urlaub</span><span>Meer</span><span>Salz</span><span>…</span></div><small>Beispielkette · im Couchspiel keine automatische Mitschrift</small>';
case 'odd':return p+'<div class="split">'+tile('FRAGE A · REVEAL','Dein bester Urlaub?')+tile('FRAGE B · REVEAL','Dein längster Urlaub?')+'</div><small>Die abweichenden Fragen erscheinen erst bei der Auflösung.</small>';
case 'panic':return p+'<div class="panic">05</div><span class="eyebrow">Beispiel · kein laufender Timer</span>';
case 'moon':return p+'<div class="rail"><span>Locker</span><span>Frech</span><span>Pause</span></div><div class="note">Die gemeinsame Grenze zählt. Jede Stimme.</div>';
case 'audio':return p+'<div class="rail"><span>1 s</span><span>3 s</span><span>7 s</span><span>15 s</span></div><div class="secret">Track bleibt verdeckt</div><small>Audiofläche · im Entwurf stumm</small>';
case 'timeline':return p+'<div class="rail"><span>1984</span><span class="accent">Dein Drop ↓</span><span>1998</span><span>2007</span></div><div class="completion">Flow: Position reicht · Präzision auf Wunsch</div>';
default:return p;
}}
function stage(){let g=current,body='',cta=g.cta;const top=`<div class="stage-top"><span>${esc(g.title)}</span><span>ENTWURF · ${view==='finale'?'AUFLÖSUNG':view==='handoff'?'SICHTSCHUTZ':'BEISPIEL'}</span></div>`;
if(view==='intro'){body=`<span class="stage-tag">SO SPIELT IHR</span><h2>${esc(g.rule)}</h2><div class="completion">${esc(g.duration)}</div><small>${esc(g.mode)}</small>`;cta='Spielmoment ansehen';}
else if(view==='finale'){body=`<span class="stage-tag">DER MOMENT BLEIBT</span><h2>${esc(g.moment)}</h2><p>${esc(g.finale)}</p><div class="completion">${esc(g.replay)}</div>`;cta='Neuen Bogen ansehen';}
else if(view==='handoff'){if(handoff===0){body='<span class="stage-tag">BEISPIEL · GEHEIME WAHL</span><h2>Ari hat gewählt.</h2><div class="secret"><small>NOCH NUR FÜR ARI</small><div class="seal">A</div><span>Fiktive Auswahl A</span></div>';cta='Versiegeln';}else if(handoff===1){body='<div class="secret"><small>VERSIEGELT</small><div class="seal">//</div><span>Die Wahl bleibt verdeckt.</span></div><div class="center"><small>GIB DAS HANDY AN</small><div class="handoff-name">Nova</div><small>Kein Timer während der Übergabe.</small></div>';cta='Ich bin Nova · bereit';}else{body='<span class="stage-tag">NOVA · JETZT DU</span><h2>Deine Wahl bleibt ebenfalls privat.</h2><p>Danach legt ihr das Handy zwischen euch und deckt gemeinsam auf.</p><div class="completion">Eine Übergabe. Ein Bereitschaftstap. Ein gemeinsamer Moment.</div>';cta='Übergabe erneut ansehen';}}
else body=art(g);
$('stage').className='stage'+(g.visual==='minimal'?' light':'');$('stage').innerHTML=top+'<div class="stage-body">'+body+'</div><div class="stage-bottom"><button class="action" id="demo-action">'+esc(cta)+'</button><button class="quiet" id="view-reset">Ansicht zurücksetzen</button></div>';
$('demo-action').onclick=()=>{if(view==='handoff'){handoff=(handoff+1)%3;stage();}else{view=view==='intro'?'moment':view==='moment'?'finale':'intro';render(false);}};$('view-reset').onclick=()=>{view='moment';handoff=0;render(false);};}
function render(updateNav=true){document.documentElement.style.setProperty('--accent',current.accent);$('world').textContent=current.world;$('mode').textContent=current.mode;$('title').textContent=current.title;$('fantasy').textContent=current.fantasy;$('finding').textContent=current.finding;$('details').innerHTML=[['device','Spielweise & Übergabe'],['layout','Art Direction'],['loop','Game Loop'],['reveal','Reveal'],['edge','Sonderfälle'],['acceptance','Abnahme']].map(([k,t])=>`<section><h3>${t}</h3><p>${esc(current[k])}</p></section>`).join('');document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===view)));if(updateNav)nav();stage();}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;handoff=0;render(false);});$('search').oninput=nav;render();
</script></body></html>'''
doc = doc.replace('__DATA__', json.dumps(games, ensure_ascii=False).replace('</', '<\\/'))
(ROOT / 'ui-ux-concept-atlas-2026.html').write_text(doc)
print(f'Generated dossier and atlas for {len(games)} games.')
